import CustomerOrder from "../models/customerOrder";



const servicesTransform = (services) => {
  let transformedServices = [];
  if (services) {
    services.map((i) => {
      transformedServices.push({
        id: i.id,
        title: i.title,
        description: i.description,
        category: i.category,
        category_title: i.category_title,
        sub_category: i.sub_category,
        sub_category_title: i.sub_category_title,
      });
    });
    return transformedServices;
  } else {
    return [];
  }
};

const paymentMethodsTransform = (paymentMethods) => {
  let transformedPaymentMethods = [];
  if (paymentMethods) {
    paymentMethods.map((i) => {
      transformedPaymentMethods.push({
        id: i.id,
        title: i.title,
        description: i.description,
        image: i.images && i.images.length ? i.images[0].image : "",
      });
    });
    return transformedPaymentMethods;
  } else {
    return [];
  }
};

const customerOrdersTransform = (customerOrders) => {
  let transformedCustomerOrders = [];
  if (customerOrders) {
    customerOrders.map((i) => {
      transformedCustomerOrders.push(
        new CustomerOrder(
          i.id,
          i.draft_id,
          i.entity,
          i.vendor,
          i.customer,
          i.customer_name,
          i.customer_phone,
          i.account,
          i.account_details ? i.account_details.title : "N/A",
          i.owner,
          i.owner_details
            ? `${i.owner_details.first_name} ${i.owner_details.last_name}`
            : "",
          i.dependant,
          i.dependant_details
            ? `${i.dependant_details.first_name} ${i.dependant_details.last_name}`
            : "",
          i.order_price_total ? i.order_price_total : 0.0,
          i.order_tax_total ? i.order_tax_total : 0.0,
          i.order_discount_total ? i.order_discount_total : 0.0,
          i.order_net_price_total ? i.order_net_price_total : 0.0,
          i.shipping_price ? i.shipping_price : 0.0,
          i.created,
          i.orderItems
        )
      );
    });
    return transformedCustomerOrders;
  } else {
    return [];
  }
};

export default {
  servicesTransform,
  paymentMethodsTransform,
  customerOrdersTransform,
};
